"use strict";
var Widget=require('$:/core/modules/widgets/widget.js').widget,ui=require('$:/plugins/huwiki/ai/i18n.js');
function Label(tree,options){this.initialise(tree,options);}Label.prototype=new Widget();
Label.prototype.render=function(parent,next){this.parentDomNode=parent;this.computeAttributes();this.key=this.getAttribute('key','');var text=this.document.createTextNode(ui.label(this.key,this.wiki));parent.insertBefore(text,next);this.domNodes=[text];};
Label.prototype.refresh=function(changed){var a=this.computeAttributes();if(a.key||changed&&changed['$:/language']){this.refreshSelf();return true;}return false;};
function Field(tree,options){this.initialise(tree,options);}Field.prototype=new Widget();
Field.prototype.render=function(parent,next){this.parentDomNode=parent;this.computeAttributes();this.source=this.getAttribute('tiddler',this.getVariable('currentTiddler'));this.field=this.getAttribute('field','caption');var t=this.wiki.getTiddler(this.source),f=t&&t.fields||{},name=this.field==='ai-category'?'category':this.field,translated=f['ai-ui-'+name+'-en'],value=ui.language(this.wiki)==='en'&&translated!==undefined?translated:f[this.field]||'';var n=this.document.createTextNode(String(value));parent.insertBefore(n,next);this.domNodes=[n];};
Field.prototype.refresh=function(changed){var a=this.computeAttributes();if(a.field||a.tiddler||changed&&(changed['$:/language']||changed[this.source])){this.refreshSelf();return true;}return false;};
exports['huwiki-ai-label']=Label;exports['huwiki-ai-field-label']=Field;
